// Builds the UAT plan (docs/UAT.md) and the form that testers fill in (docs/UAT-form.html) from docs/uat/uat-data.js.
//
//   npm run docs:uat
//
// Edit docs/uat/uat-data.js, then run this. Do not edit the two outputs by hand.
const fs = require('node:fs');
const path = require('node:path');
const { requirements, modules, dataPack, sessionNames } = require('../docs/uat/uat-data.js');

const root = path.resolve(__dirname, '..');
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const cases = modules.flatMap((m) => m.cases.map((c) => ({ ...c, module: m })));
const count = (p) => cases.filter((c) => p(c)).length;
const sessionCases = (s) => cases.filter((c) => c.module.session === s);
const MIN_PER_CASE = 4;       // minutes for a tester to do one case and say what they saw
const MIN_PER_MODULE = 3;     // minutes to move to the next part of the app
const minutes = (list) => list.reduce((t, c) => t + MIN_PER_CASE + (c.steps.length > 3 ? 2 : 0), 0);
const moduleMinutes = (m) => minutes(m.cases.map((c) => c)) + MIN_PER_MODULE;
const hours = (min) => (min / 60).toFixed(1);
const sessions = Object.fromEntries(Object.keys(sessionNames).map((k) => [k, { name: sessionNames[k], mods: modules.filter((m) => m.session === k) }]));
for (const s of Object.values(sessions)) s.min = s.mods.reduce((t, m) => t + moduleMinutes(m), 0);

// ------------------------------------------------------------------------------------------------------------ Markdown
function buildMarkdown() {
  const must = count((c) => c.priority === 'Must');
  const agreed = count((c) => c.priority === 'Agreed');
  const L = [];
  const w = (...x) => L.push(...x);
  w('# UAT plan: Study Planner System', '',
    '> Generated by `npm run docs:uat` from `docs/uat/uat-data.js`. Edit that file, not this one.', '',
    '## 1. Purpose', '',
    'Academic advisors compare each student with several versions of the study planners by hand. It is slow and often wrong. This session checks that the system does what the client asked for, one test for each requirement. The testers are Heads of Department. The team watches, records and does not help.', '',
    '## 2. What is tested', '',
    '| ID | Requirement | Source | Priority | Test |', '|---|---|---|---|---|');
  for (const r of requirements) w(`| ${r.id} | ${r.text} | ${r.source} | ${r.priority} | ${cases.filter((c) => c.req.includes(r.id)).map((c) => c.id).join(', ')} |`);
  w('', '**Must** = the client asked for it. **Agreed** = the team proposed it and the client agreed.', '',
    '## 3. How it runs', '',
    `- **Who:** at least 2 Heads of Department (testers), one team member who runs the session, one who takes notes.`,
    `- **How long:** ${cases.length} tests (${must} Must, ${agreed} Agreed) in two sessions, on one day with a lunch break or on two days. ${Object.entries(sessionNames).map(([k, n]) => `${n.split(':')[0]} takes about ${hours(sessionCases(k).length * 5 + 10)} hours (${sessionCases(k).length} tests)`).join('; ')}.`,
    '- **Order:** the sessions follow the order of the tests, from the first start to the Copilot and the web app.',
    '- **Where:** the team\'s computer, with the installed release build on a new installation. The testers log in to the portal with their own accounts. The team does not see or store a password or a student record. The student website is tested on a staging copy.',
    '- **Method:** the facilitator reads each task. The tester does it and marks Pass, Fail, Blocked or N/A, with a note. The facilitator does not show how. Do not fix anything during the session.',
    '- **Acceptance rule:** the client accepts the system when **all Must tests pass and no Critical or Major defect is open**. An Agreed test that fails is reported and the client decides.',
    '- **Severity:** Critical = student data stored or lost, a crash, or a wrong answer with no warning. Major = a requirement does not work and there is no workaround. Minor = awkward, or there is a workaround. Cosmetic = the look only.',
    '- **Before the session:** `npm run verify:full` passes on the build, the data pack is ready, and the team did one dry run. The dry run confirms the expected results below, which were written from the user guide and the code.', '',
    '## 4. Data pack', '', '| Item | Use |', '|---|---|', ...dataPack.map((d) => `| ${d.item} | ${d.use} |`), '',
    '## 5. Tests', '');
  for (const c of cases) {
    w(`### ${c.id}: ${c.title}`, '', `**Requirement:** ${c.req.join(', ')} | **Priority:** ${c.priority}`, '',
      ...c.steps.map((s, i) => `${i + 1}. ${s}`), '', `**Expected:** ${c.expected}`, '', '**Result (Pass / Fail / Blocked / N/A):** &nbsp;&nbsp; **Notes:**', '');
  }
  w('## 6. Defects, summary and sign-off', '',
    'Fill in the form `docs/UAT-form.html`. It has the tests, the defect log, a live summary and the sign-off. The tables are for a paper copy.', '',
    '| ID | Test | What went wrong | Severity | Status |', '|---|---|---|---|---|', '| | | | | |', '',
    `Must passed: _ of ${must}. Agreed passed: _ of ${agreed}. Open Critical or Major defects: _. Acceptance rule met: Yes / No.`, '',
    '| Name | Role | Date | Signature |', '|---|---|---|---|', '| | Head of Department | | |', '| | Head of Department | | |', '| | Client contact | | |', '',
    'Outcome: ☐ Accepted &nbsp;&nbsp; ☐ Accepted with conditions &nbsp;&nbsp; ☐ Not accepted &nbsp;&nbsp; Conditions:', '');
  return L.join('\n');
}

// ------------------------------------------------------------------------------------------------------------ HTML form
function buildHtml() {
  const css = fs.readFileSync(path.join(root, 'docs', 'uat', 'form.css'), 'utf8');
  const tag = { Must: 'tag-must', Agreed: 'tag-agreed', Supporting: 'tag-support' };
  const moduleHtml = modules.map((m) => `
  <div class="module-header">${esc(m.id)}. ${esc(m.name)} <span class="badge">Session ${m.session} · ${m.cases.length} cases</span></div>
  <div class="module-body">
${m.cases.map((c) => {
    const n = c.id.toLowerCase();
    return `    <div class="tc" data-priority="${c.priority}">
      <div class="tc-header"><div class="tc-meta">
        <div class="tc-id">${c.id}</div>
        <div class="tc-name">${esc(c.title)}</div>
        <span class="req-tag ${tag[c.priority]}">${c.priority}</span> ${c.req.map((r) => `<span class="req-tag">${r}</span>`).join(' ')}
      </div></div>
      <div class="tc-steps"><strong>Steps</strong>${c.steps.map((s, i) => `${i + 1}. ${esc(s)}`).join('<br>')}</div>
      <div class="tc-expected"><strong>Expected:</strong> ${esc(c.expected)}</div>
      <div class="result-row"><span class="result-label">Result:</span>
        <label class="radio-opt pass"><input type="radio" name="${n}" value="pass" /> Pass</label>
        <label class="radio-opt fail"><input type="radio" name="${n}" value="fail" /> Fail</label>
        <label class="radio-opt block"><input type="radio" name="${n}" value="blocked" /> Blocked</label>
        <label class="radio-opt na"><input type="radio" name="${n}" value="na" /> N/A</label>
      </div>
      <span class="notes-label">Notes: what you saw, what was confusing</span>
      <textarea name="notes-${n}" placeholder="Write what happened. Do not write student IDs, names or grades."></textarea>
    </div>`;
  }).join('\n')}
  </div>`).join('\n');

  const reqRows = requirements.map((r) => `<tr><td>${r.id}</td><td>${esc(r.text)}</td><td>${r.priority}</td></tr>`).join('');
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>UAT Form: Study Planner System</title>
  <!-- Generated by npm run docs:uat from docs/uat/uat-data.js. Edit the data file, not this file. -->
  <style>${css}
    .tag-must { background: #fed7d7; color: #9b2c2c; }
    .tag-agreed { background: #fefcbf; color: #744210; }
    .tag-support { background: #e2e8f0; color: #4a5568; }
    .req-table { width: 100%; border-collapse: collapse; font-size: 0.82rem; }
    .req-table td { padding: 6px 8px; border-bottom: 1px solid #f0f4f8; vertical-align: top; }
    .verdict { margin-top: 12px; padding: 12px 14px; border-radius: 8px; font-weight: 600; font-size: 0.9rem; }
    .verdict.ok { background: #f0fff4; color: #276749; border: 1.5px solid #c6f6d5; }
    .verdict.no { background: #fff5f5; color: #c53030; border: 1.5px solid #fed7d7; }
    .verdict.wait { background: #f7fafc; color: #4a5568; border: 1.5px solid #e2e8f0; }
    .summary-grid { grid-template-columns: repeat(3, 1fr); }
    .sub-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 12px; margin-bottom: 16px; }
    .sub-grid .summary-box { padding: 12px; }
    .sub-grid .num { font-size: 1.4rem; }
    @media (max-width: 600px) { .sub-grid, .summary-grid { grid-template-columns: 1fr 1fr; } }
  </style>
</head>
<body>
<div class="container">

  <div class="header">
    <h1>User Acceptance Testing: Study Planner System</h1>
    <p>Do each test case, mark the result, and write what you saw. Your answers are saved in this browser while you work. Do not write student IDs, names or grades.</p>
  </div>

  <div class="card">
    <h2>About this session</h2>
    <div class="field-row">
      <div><label>Tester name</label><input type="text" name="tester" /></div>
      <div><label>Role</label><input type="text" name="role" placeholder="For example Head of Department" /></div>
    </div>
    <div class="field-row">
      <div><label>Date</label><input type="date" name="date" /></div>
      <div><label>Session</label><select name="session"><option value="">Select</option>${Object.values(sessionNames).map((n) => `<option>${esc(n)}</option>`).join('')}</select></div>
    </div>
    <div class="field-row">
      <div><label>App version</label><input type="text" name="version" placeholder="For example 0.1.0" /></div>
      <div><label>Computer and operating system</label><input type="text" name="computer" placeholder="For example MacBook, macOS 15" /></div>
    </div>
  </div>

  <div class="card">
    <h2>What the client asked for</h2>
    <p style="font-size:0.82rem;color:#4a5568;margin-bottom:10px"><strong>Must</strong>: the client asked for it. All must pass. <strong>Agreed</strong>: the team proposed it and the client agreed. The tag of each test shows which it is.</p>
    <table class="req-table"><tbody>${reqRows}</tbody></table>
  </div>
${moduleHtml}

  <div class="card">
    <h2>Questions at the end</h2>
    <div class="field-row single"><div><label>Overall, how easy was it to do your work with the system? (1 = very hard, 5 = very easy)</label>
      <select name="ease"><option value="">Select</option><option>1 - Very hard</option><option>2 - Hard</option><option>3 - Neutral</option><option>4 - Easy</option><option>5 - Very easy</option></select></div></div>
    <div class="field-row single"><div><label>Does it solve the problem of tracking students against the study planners by hand? What is still missing?</label><textarea name="solves"></textarea></div></div>
    <div class="field-row single"><div><label>What was most useful?</label><textarea name="useful"></textarea></div></div>
    <div class="field-row single"><div><label>What was confusing or slow?</label><textarea name="confusing"></textarea></div></div>
    <div class="field-row single"><div><label>Other comments</label><textarea name="other"></textarea></div></div>
  </div>

  <div class="card">
    <h2>Defect log</h2>
    <table class="defect-table"><thead><tr>
      <th style="width:105px">Test case</th><th>What went wrong (steps to repeat it)</th><th style="width:105px">Severity</th><th style="width:100px">Status</th>
    </tr></thead><tbody id="defect-body"></tbody></table>
    <button class="add-row-btn" type="button" onclick="addDefectRow()">+ Add a defect</button>
    <p style="font-size:0.78rem;color:#718096;margin-top:8px">Critical: data stored or lost, a crash in a main flow, or a wrong answer with no warning. Major: a requirement does not work and there is no workaround. Minor: awkward, or there is a workaround. Cosmetic: the look only.</p>
  </div>

  <div class="card">
    <h2>Summary</h2>
    <div class="sub-grid">
      <div class="summary-box s-pass"><div class="num" id="must-pass">0 / 0</div><div class="lbl">Must passed</div></div>
      <div class="summary-box s-total"><div class="num" id="agreed-pass">0 / 0</div><div class="lbl">Agreed passed</div></div>
${count((c) => c.priority === 'Supporting') ? '      <div class="summary-box s-total"><div class="num" id="support-pass">0 / 0</div><div class="lbl">Supporting passed</div></div>\n' : ''}    </div>
    <div class="summary-grid">
      <div class="summary-box s-fail"><div class="num" id="count-fail">0</div><div class="lbl">Failed</div></div>
      <div class="summary-box s-block"><div class="num" id="count-block">0</div><div class="lbl">Blocked / N/A</div></div>
      <div class="summary-box s-fail"><div class="num" id="count-open">0</div><div class="lbl">Open Critical / Major</div></div>
    </div>
    <div class="pass-rate-bar"><div class="pass-rate-fill" id="pass-bar" style="width:0%"></div></div>
    <div class="pass-rate-label">Cases done: <span id="done-text">0</span> of <span id="total-text">0</span></div>
    <div class="verdict wait" id="verdict">Acceptance rule: all Must cases pass and no Critical or Major defect is open.</div>
  </div>

  <div class="card">
    <h2>Sign-off</h2>
    <div class="signoff-grid">
      <div><label>Tester name</label><input type="text" name="signname" /></div>
      <div><label>Date</label><input type="date" name="signdate" /></div>
    </div>
    <div style="margin-bottom:16px"><label style="margin-bottom:8px;display:block">Outcome</label>
      <div class="outcome-opts">
        <label class="outcome-opt"><input type="radio" name="outcome" value="accepted" /> Accepted</label>
        <label class="outcome-opt"><input type="radio" name="outcome" value="conditions" /> Accepted with conditions</label>
        <label class="outcome-opt"><input type="radio" name="outcome" value="rejected" /> Not accepted</label>
      </div></div>
    <div><label>Conditions or comments</label><textarea name="conditions"></textarea></div>
  </div>

  <div class="actions">
    <button class="btn btn-secondary" type="button" onclick="clearAll()">Clear the form</button>
    <button class="btn btn-secondary" type="button" onclick="window.print()">Print or save as PDF</button>
  </div>
</div>

<script>
  var KEY = 'study-planner-uat-form-v2';
  var SEVERITY = ['', 'Critical', 'Major', 'Minor', 'Cosmetic'];
  var STATUS = ['Open', 'Fixed', 'Retested', 'Accepted'];

  function defectRow(d) {
    d = d || {};
    var tr = document.createElement('tr');
    tr.innerHTML = '<td><input type="text" data-f="tc" placeholder="TC-..." /></td>' +
      '<td><input type="text" data-f="text" placeholder="What went wrong" /></td>' +
      '<td><select data-f="sev">' + SEVERITY.map(function (s) { return '<option>' + (s || 'Level') + '</option>'; }).join('') + '</select></td>' +
      '<td><select data-f="status">' + STATUS.map(function (s) { return '<option>' + s + '</option>'; }).join('') + '</select></td>';
    tr.querySelector('[data-f=tc]').value = d.tc || '';
    tr.querySelector('[data-f=text]').value = d.text || '';
    tr.querySelector('[data-f=sev]').selectedIndex = Math.max(0, SEVERITY.indexOf(d.sev || ''));
    tr.querySelector('[data-f=status]').selectedIndex = Math.max(0, STATUS.indexOf(d.status || 'Open'));
    document.getElementById('defect-body').appendChild(tr);
  }
  function addDefectRow() { defectRow(); }

  function collect() {
    var data = { fields: {}, radios: {}, defects: [] };
    document.querySelectorAll('input[name], select[name], textarea[name]').forEach(function (el) {
      if (el.type === 'radio') { if (el.checked) data.radios[el.name] = el.value; }
      else data.fields[el.name] = el.value;
    });
    document.querySelectorAll('#defect-body tr').forEach(function (tr) {
      data.defects.push({ tc: tr.querySelector('[data-f=tc]').value, text: tr.querySelector('[data-f=text]').value,
        sev: tr.querySelector('[data-f=sev]').value, status: tr.querySelector('[data-f=status]').value });
    });
    return data;
  }
  function save() { try { localStorage.setItem(KEY, JSON.stringify(collect())); } catch (e) { /* storage can be off */ } }
  function restore() {
    var data; try { data = JSON.parse(localStorage.getItem(KEY) || 'null'); } catch (e) { data = null; }
    if (data) {
      document.querySelectorAll('input[name], select[name], textarea[name]').forEach(function (el) {
        if (el.type === 'radio') el.checked = data.radios[el.name] === el.value;
        else if (data.fields[el.name] !== undefined) el.value = data.fields[el.name];
      });
      (data.defects || []).forEach(defectRow);
    }
    if (!document.querySelector('#defect-body tr')) defectRow();
  }
  function clearAll() {
    if (!confirm('Clear every answer in this form?')) return;
    try { localStorage.removeItem(KEY); } catch (e) { /* ignore */ }
    location.reload();
  }

  function updateSummary() {
    var by = { Must: [0, 0], Agreed: [0, 0], Supporting: [0, 0] }; // [passed, total]
    var fail = 0, block = 0, done = 0, total = 0, mustNotPassed = 0;
    document.querySelectorAll('.tc').forEach(function (tc) {
      var p = tc.dataset.priority; var r = tc.querySelector('input[type=radio]:checked');
      var v = r ? r.value : null; total++; by[p][1]++;
      if (v) done++;
      if (v === 'pass') by[p][0]++;
      else if (v === 'fail') fail++;
      else if (v === 'blocked' || v === 'na') block++;
      if (p === 'Must' && v !== 'pass') mustNotPassed++;
    });
    var open = 0;
    document.querySelectorAll('#defect-body tr').forEach(function (tr) {
      var sev = tr.querySelector('[data-f=sev]').value, st = tr.querySelector('[data-f=status]').value;
      if ((sev === 'Critical' || sev === 'Major') && (st === 'Open' || st === 'Fixed')) open++;
    });
    function set(id, t) { document.getElementById(id).textContent = t; }
    set('must-pass', by.Must[0] + ' / ' + by.Must[1]); set('agreed-pass', by.Agreed[0] + ' / ' + by.Agreed[1]); if (document.getElementById('support-pass')) set('support-pass', by.Supporting[0] + ' / ' + by.Supporting[1]);
    set('count-fail', fail); set('count-block', block); set('count-open', open); set('done-text', done); set('total-text', total);
    document.getElementById('pass-bar').style.width = (total ? Math.round(done / total * 100) : 0) + '%';
    var v = document.getElementById('verdict');
    if (done < total) { v.className = 'verdict wait'; v.textContent = 'Not finished: ' + (total - done) + ' cases have no result yet. Acceptance rule: all Must cases pass and no Critical or Major defect is open.'; }
    else if (mustNotPassed === 0 && open === 0) { v.className = 'verdict ok'; v.textContent = 'The acceptance rule is met: every Must case passed and no Critical or Major defect is open.'; }
    else { v.className = 'verdict no'; v.textContent = 'The acceptance rule is not met: ' + mustNotPassed + ' Must case(s) have not passed and ' + open + ' Critical or Major defect(s) are open.'; }
  }

  document.addEventListener('change', function () { updateSummary(); save(); });
  document.addEventListener('input', save);
  document.getElementById('defect-body').addEventListener('change', updateSummary);
  restore(); updateSummary();
</script>
</body>
</html>
`;
}

fs.writeFileSync(path.join(root, 'docs', 'UAT.md'), buildMarkdown());
fs.writeFileSync(path.join(root, 'docs', 'UAT-form.html'), buildHtml());
console.log(`UAT: ${cases.length} tests. Wrote docs/UAT.md and docs/UAT-form.html.`);
